contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // single public entry performing the minimal interactions and final assertion
    function run(address caller, bool makeAdmin) public {
        // Precondition: caller must not be address(0) to be meaningful
        require(caller != address(0));

        // Set admin mapping by calling into C's public state if possible.
        // The contract C exposes 'isAdmin' public mapping; we cannot write it directly from here.
        // However, C has no setter for isAdmin in the provided source, so we rely on the following approach:
        // If makeAdmin is true, we assert that caller is already an admin (observable via getter). If false, assert caller is not an admin.
        // This keeps the test general: it distinguishes behavior when caller is admin vs not-admin.

        bool callerIsAdmin = c.isAdmin(caller);
        if (makeAdmin) {
            require(callerIsAdmin, "precondition: caller must already be admin when makeAdmin is true");
        } else {
            require(!callerIsAdmin, "precondition: caller must not be admin when makeAdmin is false");
        }

        // Try to invoke newEmergencyOracle as 'caller' by using a low-level call to simulate msg.sender = caller.
        // We cannot change msg.sender directly in Solidity, but we can observe whether a call from this contract (not 'caller') would revert.
        // To keep things strictly within the rules (only interact via c's public surface), we perform a call from this contract and observe revert behavior.
        // The property we're asserting compares the revert outcome for admin vs non-admin callers as observed via the mapping.

        // Call newEmergencyOracle from this contract (msg.sender = address(this)) and record whether it reverts.
        bytes memory payload = abi.encodeWithSignature("newEmergencyOracle(string)", "desc");
        (bool ok, ) = address(c).call(payload);
        bool callSucceeded = ok;

        // RULE: If the mapping reports that this contract (address(this)) is an admin, then calling newEmergencyOracle from this contract should succeed; otherwise it should revert.
        // This rule captures the intended access-control: only admins may call the function. It is true for the original contract P and violated by the mutant which flips the require.
        bool thisIsAdmin = c.isAdmin(address(this));

        assert(thisIsAdmin == callSucceeded);
    }

    // allow receiving ether if needed
    receive() external payable {}
    fallback() external payable {}
}

